async function selectStall(n,{reveal=false}={}){const s=stalls.find(x=>x.n===Number(n));if(!s)return;const intent=++selectionIntent,returnFocus=document.activeElement;enquiryIntent++;enquiryOpening=false;selectionChecking=true;renderBookingStatus();$('#scene-wrap').dataset.bookingChecking='true';$('#scene-wrap').dataset.bookingCheckLabel=t('bookingChecking');const decision=await bookings.checkStall(s.n);if(intent!==selectionIntent)return;selectionChecking=false;$('#scene-wrap').dataset.bookingChecking='false';renderBookingStatus();if(!decision.allowed){statusRefusal(s,decision,{returnFocus,retry:()=>selectStall(s.n,{reveal})});return;}if(s.hall!==hall)switchHall(s.hall);const changed=selected?.n!==s.n;selected=s;stopAutoUI();explorer?.select(s.n,view==='3d');if(changed)renderDetail();syncDirectorySelection();renderFlat();updateSelectionPin();showHover(null);if(view==='2d')plan?.focus(s.n,{immediate:paused});if(changed&&!paused)$('#stall-detail').animate([{opacity:.65},{opacity:1}],{duration:200,easing:'ease-out'});if(reveal&&!document.fullscreenElement&&!$('#hall-workspace').classList.contains('map-expanded'))$('#hall-workspace').scrollIntoView({block:'start',behavior:paused?'auto':'smooth'});if(decision.status==='reserved')statusNotice.show('reserved',{stall:s.n,returnFocus});}
function statusRefusal(stall,decision,{retry=null,returnFocus=null}={}){if(decision.reason==='sold_out'){if(selected?.n===stall.n)clearSelection({cancelIntent:false});if(dialog.open&&enquiryStall?.n===stall.n)dialog.close();statusNotice.show('sold_out',{stall:stall.n,returnFocus});}else statusNotice.show('unknown',{stall:stall.n,retry,returnFocus});}

function syncDirectorySelection(){for(const b of $('#stall-directory').querySelectorAll('[data-stall]')){const active=Number(b.dataset.stall)===selected?.n;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));}}

function clearSelection({cancelIntent=true}={}){if(cancelIntent){selectionIntent++;enquiryIntent++;enquiryOpening=false;selectionChecking=false;$('#scene-wrap').dataset.bookingChecking='false';renderBookingStatus();}selected=null;explorer?.clear();plan?.update({selected:null});renderDetail();renderDirectory();updateSelectionPin();}
