function placePin(p){const el=$('#selection-pin');if(!selected||!p?.visible){el.hidden=true;return;}el.hidden=false;const r=$('#scene-wrap').getBoundingClientRect();pinSize??={width:el.offsetWidth,height:el.offsetHeight};const position=calloutPosition(p,r,pinSize,el.classList.contains('pin-below'));if(position.hidden){el.hidden=true;return;}el.classList.toggle('pin-below',position.below);el.style.left=position.x+'px';el.style.top=position.y+'px';}

function showHover(hit){const el=$('#map-hover');if(!hit||hit.n===selected?.n){el.hidden=true;return;}const s=stalls[hit.n-1],r=$('#scene-wrap').getBoundingClientRect();el.innerHTML=`<span style="background:${colors[s.color]}"></span><div><strong>${t('stall')} ${s.n}</strong><small>${t(s.tier)} · ${money(s.price)}</small>${bookings.statusFor(s.n)?`<small class="hover-stall-status" data-status="${bookings.statusFor(s.n)}">${statusLabel(bookings.statusFor(s.n))}</small>`:''}</div>`;el.hidden=false;el.style.left=Math.max(10,Math.min(r.width-210,hit.clientX-r.left+16))+'px';el.style.top=Math.max(65,Math.min(r.height-80,hit.clientY-r.top-50))+'px';}
