function setView(v){const changed=view!==v;view=v;showHover(null);$('#scene').hidden=v!=='3d';$('#flat-map').hidden=v!=='2d';$$('[data-view]').forEach(b=>{const active=b.dataset.view===v;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});$('#scene-hint').textContent=t(v==='3d'?'controlsHint':'flatHint');$('#tour').disabled=v==='2d'||!has3d;$('#rotate').disabled=v==='2d'||!has3d;$('#top-view').disabled=v==='2d'||!has3d;$('#scene-loader').hidden=v!=='3d'||has3d;explorer?.setVisible(v==='3d');if(v==='2d'){explorer?.setTour(false);explorer?.setOrbit(false);stopAutoUI();plan?.projectPin();}else if(!has3d)ensureScene();updateSelectionPin();if(changed&&selected)focusSelected();}
