function jumpToQuery(){const n=Number($('#stall-search').value.trim());if(n===198)selectStall(149,{reveal:true});else if(Number.isInteger(n)&&n>=1&&n<=193)selectStall(n,{reveal:true});}
$('#stall-search').oninput=()=>{renderDirectory();const n=Number($('#stall-search').value.trim());$('#search-go').disabled=!(Number.isInteger(n)&&((n>=1&&n<=193)||n===198));};
