function renderFlat(){plan?.update({selected:selected?.n??null,category:$('#category').value,directions});}
function statusLabel(status){return t({available:'bookingAvailable',reserved:'bookingReserved',sold_out:'bookingSoldOut'}[status]??'bookingUnknownTitle');}
function bookingDetailMarkup(n){const status=bookings.statusFor(n);return `<div class="detail-booking-line" data-booking-selected data-status="${status||'unknown'}" ${status?'':'hidden'}><span class="booking-badge" data-booking-selected-badge>${status?statusLabel(status):''}</span><small data-booking-selected-note>${status==='reserved'?t('bookingReservedWarning'):bookings.state!=='live'?t('bookingLastKnown'):''}</small></div>`;}
function mountBookingStatus(){const line=document.createElement('div');line.id='booking-status';line.className='booking-status-line';line.innerHTML='<span class="booking-legend booking-legend-reserved"></span><span class="booking-legend booking-legend-sold-out"></span><span class="booking-status-copy" role="status" aria-live="polite"></span><span class="booking-status-time" aria-live="off"></span><span class="booking-status-note"></span>';$('#hall-workspace .explorer-search').insertAdjacentElement('afterend',line);if(typeof ResizeObserver!=='undefined'){const observer=new ResizeObserver(()=>$('#hall-workspace').style.setProperty('--booking-status-height',line.getBoundingClientRect().height+'px'));observer.observe(line);}return line;}
function renderBookingStatus(){const state=bookings.state;bookingStatusElement.dataset.state=state;bookingStatusElement.setAttribute('aria-label',t('bookingStatusLabel'));const text=(selector,value)=>{const el=bookingStatusElement.querySelector(selector);if(el.textContent!==value)el.textContent=value;};text('.booking-legend-reserved',t('bookingReserved'));text('.booking-legend-sold-out',t('bookingSoldOut'));text('.booking-status-copy',t(selectionChecking||enquiryOpening||enquiryBusy?'bookingChecking':{loading:'bookingLoading',live:'bookingSynced',stale:'bookingStale',offline:'bookingOffline'}[state]));text('.booking-status-note',t('bookingNote'));const time=bookings.lastSynced===null?'':new Intl.DateTimeFormat(getLang().locale,{timeZone:'Asia/Kolkata',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(bookings.lastSynced));text('.booking-status-time',time?`${t('bookingLastSync')} ${time}`:'');}
function syncDirectoryBookings(){for(const b of $('#stall-directory').querySelectorAll('[data-stall]')){const s=stalls[Number(b.dataset.stall)-1],status=bookings.statusFor(s.n);for(const value of ['available','reserved','sold_out'])b.classList.toggle('is-'+value.replace('_','-'),status===value);b.classList.toggle('is-booked',status==='reserved'||status==='sold_out');b.setAttribute('aria-disabled',String(status==='sold_out'));const marker=b.querySelector('.directory-booked');if(marker){marker.hidden=status!=='reserved'&&status!=='sold_out';marker.dataset.status=status||'unknown';marker.textContent=status==='reserved'?'R':status==='sold_out'?'S':'';marker.title=status?statusLabel(status):'';}b.setAttribute('aria-label',`${t('hall')} ${s.hall}, ${t('stall')} ${s.n}, ${t(s.tier)}, ${money(s.price)}${status?', '+statusLabel(status):''}`);}}
function syncQuickPickBookings(){for(const b of $('#stall-detail').querySelectorAll('[data-pick]')){const n=Number(b.dataset.pick),status=bookings.statusFor(n);for(const value of ['available','reserved','sold_out'])b.classList.toggle('is-'+value.replace('_','-'),status===value);b.setAttribute('aria-disabled',String(status==='sold_out'));b.setAttribute('aria-label',`${t('stall')} ${n}${status?', '+statusLabel(status):''}`);b.title=status?statusLabel(status):'';}}
function syncSelectedBooking(){const line=$('[data-booking-selected]');if(!line)return;const status=selected?bookings.statusFor(selected.n):null;line.hidden=!status;line.dataset.status=status||'unknown';const badge=line.querySelector('[data-booking-selected-badge]');if(badge)badge.textContent=status?statusLabel(status):'';const note=line.querySelector('[data-booking-selected-note]');if(note)note.textContent=status==='reserved'?t('bookingReservedWarning'):bookings.state!=='live'?t('bookingLastKnown'):'';}
function syncBookingStatus(snapshot){renderBookingStatus();syncSelectedBooking();syncQuickPickBookings();if(statusNotice.open&&['reserved','sold_out'].includes(statusNotice.kind)&&snapshot.statuses.get(statusNotice.stall)==='available')statusNotice.close();if(snapshot.changed){syncDirectoryBookings();plan?.setBookings(snapshot.booked,snapshot.statuses);explorer?.setBookings(snapshot.booked,snapshot.statuses);updateSelectionPin();}const blocked=[selected?.n,dialog.open?enquiryStall?.n:null].find(n=>n&&snapshot.statuses.get(n)==='sold_out');if(blocked){if(selected?.n===blocked)clearSelection({cancelIntent:false});if(dialog.open&&enquiryStall?.n===blocked)dialog.close();statusNotice.show('sold_out',{stall:blocked});}else if(dialog.open&&enquiryStall){const previous=enquiryStall.status;enquiryStall.status=bookings.statusFor(enquiryStall.n);renderEnquiry();if(enquiryStall.status==='reserved'&&previous!=='reserved')statusNotice.show('reserved',{stall:enquiryStall.n});}}

function renderTariffs(){for(const h of[1,2]){$(`#tariff-${h}`).innerHTML=Object.entries(tiers).filter(([,v])=>v.hall===h).map(([key,v],i)=>{const list=stalls.filter(s=>s.tier===key);const sizes=[...new Set(list.map(s=>s.size))];const spec=sizes.length===1&&sizes[0]?sizes[0]:t('multiSize');const grouped=sizes.map(size=>`<div class="size-row"><strong>${size||t('confirmSize')}</strong>${list.filter(s=>s.size===size).map(s=>s.n).join(', ')}</div>`).join('');return`<article class="tariff-card ${i===0?'featured':''}"><div class="tariff-card-header"><div class="tariff-label"><span>${t(key)}</span><span aria-hidden="true">${i===0?'✦':'↗'}</span></div><div class="tariff-price">${money(v.price)}</div><p class="tariff-subtitle">${v.count} ${t(i===0?'premium':i===1?'exclusive':'standard')}</p></div><div class="tariff-card-content"><div class="tariff-spec"><strong>${spec}</strong></div><details><summary>${t('seeStalls')}</summary><div class="tariff-number-list">${grouped}</div></details><button class="text-link" data-tier="${key}"><span>${t('bookStall')}</span>${icon('arrowUpRight')}</button></div></article>`;}).join('');}$('[data-zone-link]').onclick=()=>{switchHall(2);$('#halls').scrollIntoView({behavior:paused?'auto':'smooth'});};$$('[data-tier]').forEach(b=>b.onclick=()=>{const tier=b.dataset.tier;switchHall(tiers[tier].hall);$('#category').value=tier;renderDirectory();$('#halls').scrollIntoView({behavior:paused?'auto':'smooth'});});}
const dayIcons=['scissors','star','trophy','award'];
function renderProgramme(){$('#programme-tabs').innerHTML=dates.map((d,i)=>`<button id="day-tab-${i}" role="tab" aria-selected="${day===i}" aria-controls="programme-panel" class="${day===i?'active':''}" tabindex="${day===i?0:-1}" data-day="${i}"><span class="day-number">0${i+1}</span><span><b>${t('day')} ${i+1}</b>${date(d)}</span></button>`).join('');$('#programme-panel').setAttribute('aria-labelledby',`day-tab-${day}`);$('#programme-panel').innerHTML=`<div class="programme-art" aria-hidden="true">${icon(dayIcons[day])}</div><div><h3>${t(`day${day+1}Title`)}</h3><p>${t(`day${day+1}Body`)}</p></div>`;$$('[data-day]').forEach(b=>{b.onclick=()=>{day=Number(b.dataset.day);renderProgramme();};b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();day=e.key==='Home'?0:e.key==='End'?3:(day+(e.key==='ArrowRight'?1:3))%4;renderProgramme();$(`[data-day="${day}"]`).focus();}};});}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
