function enquiryDetails(){return{name:$('#enquiry-name').value,phone:$('#enquiry-phone').value,business:$('#enquiry-business').value,message:$('#enquiry-message').value};}
function validateEnquiry(){const details=enquiryDetails();$('#enquiry-name').setCustomValidity(details.name.trim()?'':t('waNameRequired'));$('#enquiry-phone').setCustomValidity(validEnquiryPhone(details.phone)?'':t('waPhoneInvalid'));}
function setEnquiryBusy(value){enquiryBusy=value;enquiryForm.setAttribute('aria-busy',String(value));for(const el of enquiryForm.querySelectorAll('input,textarea,button[type=submit]'))el.disabled=value;renderBookingStatus();if(dialog.open)renderEnquiry();}
async function openEnquiry(s=selected){selectionIntent++;selectionChecking=false;enquiryOpening=false;$('#scene-wrap').dataset.bookingChecking='false';const stall=s?{...s}:null,intent=++enquiryIntent,returnFocus=document.activeElement;if(stall){enquiryOpening=true;renderBookingStatus();const decision=await bookings.checkStall(stall.n);if(intent!==enquiryIntent)return;enquiryOpening=false;renderBookingStatus();if(!decision.allowed){statusRefusal(stall,decision,{returnFocus,retry:()=>openEnquiry(stall)});return;}stall.status=decision.status;}enquiryStall=stall;enquiryPreparedAt=new Date();renderEnquiry();if(!dialog.open)dialog.showModal();if(stall?.status==='reserved')statusNotice.show('reserved',{stall:stall.n});}
function renderEnquiry(){const status=enquiryStall?bookings.statusFor(enquiryStall.n):null;if(enquiryStall)enquiryStall.status=status;$('#enquiry-selection').textContent=enquiryStall?`${t('hall')} ${enquiryStall.hall} · ${t('stall')} ${enquiryStall.n}\n${t(enquiryStall.tier)} · ${money(enquiryStall.price)} · ${enquiryStall.size||t('confirmSize')}\n${status?statusLabel(status):t('bookingUnknownTitle')}`:t('waGeneral');validateEnquiry();enquiryCheckMessage.textContent=enquiryBusy?t('bookingChecking'):enquiryStall&&bookings.state!=='live'?t('bookingEnquiryUnavailable'):status==='reserved'?t('bookingReservedWarning'):status==='sold_out'?t('bookingSoldOutWarning'):'';enquiryCheckMessage.dataset.status=status||'unknown';$('#enquiry-draft').value=enquiryStall&&(!status||status==='sold_out')?'':buildEnquiryDraft({stall:enquiryStall,status,details:enquiryDetails(),preparedAt:enquiryPreparedAt,t,money,locale:getLang().locale});enquiryForm.querySelector('[type=submit]').disabled=enquiryBusy||status==='sold_out';}
enquiryForm.addEventListener('input',renderEnquiry);enquiryForm.addEventListener('change',renderEnquiry);enquiryForm.querySelector('[type=submit]').addEventListener('click',validateEnquiry);
enquiryForm.addEventListener('submit',e=>{validateEnquiry();if(!enquiryForm.reportValidity()){e.preventDefault();return;}if(!enquiryStall){enquiryPreparedAt=new Date();renderEnquiry();return;}e.preventDefault();if(enquiryBusy)return;const stall={...enquiryStall},intent=++enquiryIntent;guardedWhatsAppHandoff({stall,checkStatus:n=>bookings.checkStall(n),isCurrent:()=>intent===enquiryIntent&&dialog.open&&enquiryStall?.n===stall.n,getDraft:status=>{const details=enquiryDetails();if(!details.name.trim()||!validEnquiryPhone(details.phone))throw new Error('Invalid enquiry details');enquiryStall={...stall,status};enquiryPreparedAt=new Date();renderEnquiry();return $('#enquiry-draft').value;},onChecking:value=>{if(intent===enquiryIntent)setEnquiryBusy(value);},onBlocked:decision=>{if(intent===enquiryIntent)statusRefusal(stall,decision,{retry:()=>enquiryForm.requestSubmit()});},checkingText:t('bookingChecking')});});
$$('[data-whatsapp]').forEach(b=>b.onclick=()=>openEnquiry());
$$('[data-enquire]').forEach(b=>b.onclick=()=>openEnquiry());$('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{enquiryIntent++;enquiryOpening=false;enquiryBusy=false;for(const el of enquiryForm.querySelectorAll('input,textarea,button[type=submit]'))el.disabled=false;enquiryForm.setAttribute('aria-busy','false');renderBookingStatus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
$('#menu-toggle').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',open);};$('#navigation').querySelectorAll('a').forEach(a=>a.onclick=()=>{$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');});
$('#motion').onclick=()=>{paused=!paused;explorer?.setPaused(paused);$('#motion').innerHTML=icon(paused?'play':'pause');$('#motion').setAttribute('aria-pressed',paused);$('#motion').setAttribute('aria-label',t(paused?'resume':'pause'));document.body.classList.toggle('motion-paused',paused);};
$('#rotate').onclick=()=>{const on=$('#rotate').getAttribute('aria-pressed')!=='true';$('#rotate').setAttribute('aria-pressed',on);$('#tour').setAttribute('aria-pressed','false');renderTour(null);explorer?.setOrbit(on);};
$('#tour').onclick=()=>{const on=$('#tour').getAttribute('aria-pressed')!=='true';$('#tour').setAttribute('aria-pressed',on);$('#rotate').setAttribute('aria-pressed','false');explorer?.setTour(on);if(!on)renderTour(null);};
$('#reset').onclick=()=>{plan?.reset();explorer?.reset();stopAutoUI();};
$('#top-view').onclick=()=>{explorer?.topView();stopAutoUI();};
$('#directions-toggle').onclick=()=>{directions=!directions;$('#directions-toggle').setAttribute('aria-pressed',directions);explorer?.setDirections(directions);renderFlat();};
$('#expand').onclick=async()=>{const el=$('#hall-workspace');if(el.classList.contains('map-expanded')){el.classList.remove('map-expanded');return;}if(document.fullscreenElement){await document.exitFullscreen();return;}try{await el.requestFullscreen();}catch{el.classList.add('map-expanded');}};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#hall-workspace').classList.remove('map-expanded');});
function zoomMap(factor){view==='3d'?explorer?.zoom(factor):plan?.zoom(factor);}
$('#zoom-in').onclick=()=>zoomMap(1.25);$('#zoom-out').onclick=()=>zoomMap(1/1.25);
const callbacks={onHover:showHover,onPin:p=>{if(view==='3d')placePin(p);},onStop:stopAutoUI,onTour:renderTour};
plan=new PlanView($('#flat-map'),n=>selectStall(n),showHover,p=>{if(view==='2d')placePin(p);},()=>({t,lang:getLang().code}));
window.addEventListener('localechange',localize);window.addEventListener('resize',()=>{pinSize=null;plan?.projectPin();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.open&&!statusNotice.open)clearSelection();});fillIcons();localize();if(paused){document.body.classList.add('motion-paused');$('#motion').innerHTML=icon('play');$('#motion').setAttribute('aria-pressed','true');}
let scenePromise=null;
async function ensureScene(){if(scenePromise)return scenePromise;scenePromise=(async()=>{let candidate=null;try{const probe=document.createElement('canvas'),gl=probe.getContext('webgl2',{failIfMajorPerformanceCaveat:true});if(!gl)throw new Error('Use compatible renderer');gl.getExtension('WEBGL_lose_context')?.loseContext();const{HallExplorer}=await import('./scene.js?v=f4cdcbaf668f40cd');candidate=new HallExplorer($('#scene'),n=>selectStall(n),()=>({t,lang:getLang().code}),callbacks);candidate.init(hall,paused);rendererName='webgl';}catch{candidate?.destroy?.();$('#scene').replaceChildren();const{HallExplorer}=await import('./canvas-scene.js?v=f4cdcbaf668f40cd');candidate=new HallExplorer($('#scene'),n=>selectStall(n),()=>({t,lang:getLang().code}),callbacks);candidate.init(hall,paused);rendererName='software';}explorer=candidate;has3d=true;$('#scene canvas').dataset.renderer=rendererName;explorer.filter($('#category').value);explorer.setBookings(bookings.booked,bookings.statuses);explorer.setDirections(directions);if(selected)explorer.select(selected.n,view==='3d');explorer.setVisible(view==='3d');setView(view);$('#scene-loader').hidden=true;})().catch(error=>{explorer=null;has3d=false;$('#scene-loader').hidden=true;$('[data-view="3d"]').disabled=true;setView('2d');console.warn('Hall view fallback:',error.message);});return scenePromise;}
const sceneObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){sceneObserver.disconnect();ensureScene();}},{rootMargin:'500px'});sceneObserver.observe($('#scene-wrap'));
// DOM controls and both renderers share one selected-stall state.
window.expo={get state(){return{hall,selected:selected?.n,view,language:getLang().code,has3d,paused,directions,renderer:rendererName};},get stallCount(){return stalls.length;}};

bookings.start();
